import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.BbQrW5_t.js";const u=JSON.parse('{"title":"操作系统与内网概念","description":"","frontmatter":{"title":"操作系统与内网概念","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","初级"]},"headers":[],"relativePath":"study/cyber-security/chapters/初级篇/05-操作系统与内网概念.md","filePath":"study/cyber-security/chapters/初级篇/05-操作系统与内网概念.md","lastUpdated":1788493831000}'),n={name:"study/cyber-security/chapters/初级篇/05-操作系统与内网概念.md"};function l(o,t,d,r,p,h){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="_05-·-操作系统与内网概念——为第-2-年打地基" tabindex="-1">05 · 操作系统与内网概念——为第 2 年打地基 <a class="header-anchor" href="#_05-·-操作系统与内网概念——为第-2-年打地基" aria-label="Permalink to &quot;05 · 操作系统与内网概念——为第 2 年打地基&quot;">​</a></h1><blockquote><p>内网渗透听起来吓人，地基其实是两块：<strong>Windows 域的协作模型</strong>和<strong>Linux 的权限边界</strong>。本章只建立&quot;地图&quot;，攻击手法全部留在第 2 年（且仅在授权环境）。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>画出公司&quot;域环境&quot;的典型拓扑，说清每类角色的职责</li><li>用流程图讲一遍 Kerberos 认证（概念级，不涉及攻击）</li><li>掌握 Linux 提权排查清单的 5 个位置（本地虚拟机复现）</li><li>说清密码存储的演进与&quot;为什么加盐&quot;</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_5-1-windows-域-企业为什么用它" tabindex="-1">5.1 Windows 域：企业为什么用它 <a class="header-anchor" href="#_5-1-windows-域-企业为什么用它" aria-label="Permalink to &quot;5.1 Windows 域：企业为什么用它&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                ┌──────────────┐</span></span>
<span class="line"><span>                │  域控制器 DC  │  ← AD 数据库(NTDS.dit)、Kerberos 发证机构</span></span>
<span class="line"><span>                └──────┬───────┘</span></span>
<span class="line"><span>        ┌──────────────┼──────────────┐</span></span>
<span class="line"><span>   ┌────┴────┐    ┌────┴────┐    ┌────┴────┐</span></span>
<span class="line"><span>   │ 文件服务器│    │ OA/业务机│    │ 员工 PC  │   ← 全部加入域，统一身份</span></span>
<span class="line"><span>   └─────────┘    └─────────┘    └─────────┘</span></span></code></pre></div><ul><li>一处建账号，全网通用——管理便利（IT 的理由）</li><li><strong>一次凭据全网有效</strong>——攻击者的黄金乡（安全的代价）</li><li>组策略（GPO）：下发配置/脚本/策略的机制</li><li>概念词表：DC（域控）、AD（活动目录）、Domain Admin（域管，&quot;上帝账号&quot;）、Workstation/Server</li></ul><h3 id="_5-2-kerberos-认证-概念流程" tabindex="-1">5.2 Kerberos 认证（概念流程） <a class="header-anchor" href="#_5-2-kerberos-认证-概念流程" aria-label="Permalink to &quot;5.2 Kerberos 认证（概念流程）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 ──① AS-REQ(用自己的密码哈希加密的时间戳)──&gt; KDC/AS</span></span>
<span class="line"><span>     &lt;──② AS-REP(TGT票据)─────────────────────  验明正身，发票</span></span>
<span class="line"><span>用户 ──③ TGS-REQ(TGT + 要访问的服务)─────────&gt; KDC/TGS</span></span>
<span class="line"><span>     &lt;──④ TGS-REP(服务票据 ST)────────────────  发服务票</span></span>
<span class="line"><span>用户 ──⑤ ST──&gt; 目标服务器  验票放行</span></span></code></pre></div><p>三个角色：<strong>KDC</strong>（发证的，在 DC 上）、<strong>TGT</strong>（身份凭证缓存）、<strong>ST</strong>（单服务门票）。第 2 年的&quot;域攻击面&quot;几乎全部围绕&quot;票据在哪些环节可以被骗取/伪造&quot;——先把正常流程刻进脑子。</p><h3 id="_5-3-linux-提权排查清单-本地虚拟机复现" tabindex="-1">5.3 Linux 提权排查清单（本地虚拟机复现） <a class="header-anchor" href="#_5-3-linux-提权排查清单-本地虚拟机复现" aria-label="Permalink to &quot;5.3 Linux 提权排查清单（本地虚拟机复现）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>命令</th><th>想找什么</th></tr></thead><tbody><tr><td>SUID 文件</td><td><code>find / -perm -4000 -type f 2&gt;/dev/null</code></td><td>非默认路径的 SUID（如 /tmp 下的）</td></tr><tr><td>sudo 权限</td><td><code>sudo -l</code></td><td>(ALL) NOPASSWD 或可绕过的程序</td></tr><tr><td>cron 任务</td><td><code>crontab -l; ls /etc/cron*</code></td><td>root 跑的、可写路径的脚本</td></tr><tr><td>可写服务</td><td><code>find /etc -writable -ls 2&gt;/dev/null</code></td><td>systemd 单元指向可写脚本</td></tr><tr><td>Capabilities</td><td><code>getcap -r / 2&gt;/dev/null</code></td><td>cap_setuid 等</td></tr></tbody></table><p><strong>最小复现实验（自建环境）</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 制造一个&quot;可被提权&quot;的 SUID（教学用，实验后删除）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /bin/find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/find_demo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u+s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/find_demo</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># find 的 -exec 会以文件属主身份执行命令——SUID + find = 经典路径</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/tmp/find_demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whoami</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 观察输出：root（实验环境）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/find_demo</span></span></code></pre></div><p>理解要点：SUID 提权的本质 = &quot;特权程序能否被我诱导执行我指定的动作&quot;。</p><h3 id="_5-4-密码的存储与破解-概念" tabindex="-1">5.4 密码的存储与破解（概念） <a class="header-anchor" href="#_5-4-密码的存储与破解-概念" aria-label="Permalink to &quot;5.4 密码的存储与破解（概念）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>说明</th><th>被拖库后</th></tr></thead><tbody><tr><td>明文</td><td>原始存储</td><td>全灭（不该存在于 2026 年）</td></tr><tr><td>纯 MD5/SHA1</td><td>快哈希</td><td>GPU 每秒百亿次，秒破弱口令</td></tr><tr><td>MD5+盐</td><td>加随机串</td><td>拖慢彩虹表，挡不住 GPU 暴破</td></tr><tr><td>bcrypt/scrypt/Argon2</td><td>慢哈希+可调成本</td><td>每次尝试毫秒级，暴破成本指数上升</td></tr></tbody></table><p>hashcat 的角色：<code>-m 0</code> MD5、<code>-m 3200</code> bcrypt……模式编号即算法字典。<strong>破解概念=用算力换可能性</strong>，而防御答案是&quot;让每次尝试足够慢&quot;。</p><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><ol><li>虚拟机装一个 Ubuntu Server + 一个 Windows 10（不起域，先认界面）</li><li>完成 5.3 提权清单的 5 项排查，记录&quot;这台机器哪里能提权&quot;</li><li>用 Python 计算 <code>md5/sha256/bcrypt(&quot;123456&quot;)</code> 感受耗时差异（bcrypt 调 cost=10）</li></ol><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>跳过&quot;正常流程&quot;直接背攻击手法——地基不牢第 2 年全返工</li><li>把 Kerberos 当黑盒——它是域攻防的全部语法</li><li>在公司电脑上练提权排查——<strong>只在自己虚拟机里做</strong></li><li>轻视&quot;慢哈希&quot;——这是全行业口令安全的胜负手</li><li>混淆&quot;认证&quot;（你是谁）与&quot;授权&quot;（你能干什么）</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 域环境给 IT 和攻击者各带来什么？</summary><p>IT：单点身份+统一策略，管理成本骤降。攻击者：一次凭据泄露=全网横行的可能，域管账号成为最高价值目标。</p></details><details><summary>2. TGT 和 ST 的区别？</summary><p>TGT 是向 KDC 证明身份的&quot;身份证&quot;（缓存于本机，用于申请各服务票据）；ST 是访问单一服务的&quot;门票&quot;，由目标服务用其机器账户密钥验证。</p></details><details><summary>3. find -perm -4000 在提权排查里的逻辑？</summary><p>SUID 程序以属主权限运行；若属主是 root 且程序支持执行外部命令（如 find -exec、vim :!、nmap interactive），普通用户即可借道执行 root 指令。</p></details><details><summary>4. 为什么 bcrypt 比 MD5 适合存密码？</summary><p>bcrypt 内置盐+可调慢因子（cost），使单次哈希刻意耗时（~100ms 量级），GPU 暴破成本指数抬升；MD5 的设计目标是快。</p></details><details><summary>5. &quot;认证&quot;与&quot;授权&quot;各举一例？</summary><p>认证：Kerberos 验明&quot;你是张三&quot;。授权：ACL/GPO 判定&quot;张三能否读财务盘&quot;。常见漏洞是把认证当授权（如前端隐藏按钮但后端不校验）。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li>对应计划：<strong>第1年 W22-W25</strong>；资源：《内网安全攻防》第 1-2 章（预读）、Microsoft Kerberos 文档、GTFOBins（SUID 提权字典）</li></ul>`,31)])])}const k=a(n,[["render",l]]);export{u as __pageData,k as default};
